        new_items = story.get("news_items", []) or []
        new_hashes = [ni.get("hash") for ni in new_items if ni.get("hash")]

        hashes_to_remove = self._check_news_item_to_remove(existing_hashes, new_hashes)
        if not hashes_to_remove:
