      responses:
        '200':
          description: server is alive
          content:
            application/json:
              schema:
                type: object
                properties:
                  isalive:
                    type: boolean
                    examples:
                    - true
  /health:
    get:
      tags:
      - health
      operationId: health.get
      description: see whether the Taranis instance dependencies are healthy
      security: []
      responses:
        '200':
          description: all required services are healthy
          content:
            application/json:
              schema:
                type: object
                properties:
                  healthy:
                    type: boolean
                    examples:
                    - true
                  services:
                    type: object
                    properties:
                      database:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      broker:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      workers:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
        '503':
          description: one or more required services are unhealthy
          content:
            application/json:
              schema:
                type: object
                properties:
                  healthy:
                    type: boolean
                    examples:
                    - false
                  services:
                    type: object
                    properties:
                      database:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      broker:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      workers:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
