--- src/frontend/frontend/static/assets/openapi3_1.yaml ---
openapi: 3.1.0
info:
  title: Taranis AI
  contact:
    name: Benjamin Akhras
    url: https://taranis.ai
    email: taranis@list.ait.ac.at
  description: The Taranis API provides endpoints for the Taranis is an OSINT gathering
    and analysis tool.
  license:
    name: EUPL-1.2
    url: https://eupl.eu/1.2/en/
  version: 1.3.6
externalDocs:
  description: GitHub
  url: https://github.com/taranis-ai/taranis-ai/
servers:
- url: /api
  description: default
tags:
- name: auth
  description: session-related functionality
- name: health
  description: see whether Taranis dependencies are healthy
- name: realtime
  description: authenticate Centrifugo realtime connections
- name: isalive
  description: see whether the Taranis instance is alive
- name: users
  description: read/update the profile, get wordlists, product types and publisher
    presets
- name: analyze
  description: read/update report items, their types, groups and attributes
- name: assess
  description: read/update/delete OSINT sources and news items
- name: assets
  description: read/update/delete asset groups, notification templates and attributes
- name: bots
  description: read/update/delete bots-related information
- name: collectors
  description: read/update/delete collectors (OSINT sources)
- name: config
  description: read/update/delete everything config-related
- name: dashboard
  description: get dashboard data
- name: presenters
  description: get all presenters nodes
- name: publish
  description: read/update/delete/publish products
- name: publishers
  description: read/update/delete publisher nodes/presets
security:
- APIKey: []
- UserAuth: []
paths:
  /auth/login:
    post:
      tags:
      - auth
      operationId: auth.login.post
      description: authenticate with either username and password
      security: []
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/req.auth.username_password'
      responses:
        '200':
          description: successful authentication
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/resp.auth.JWT'
        '400':
          description: resource not found
        '401':
          description: authentication error (username + password)
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
        '500':
          description: Internal server error
  /auth/refresh:
    get:
      tags:
      - auth
      operationId: auth.refresh.get
      description: refresh an access token for CLI and other non-browser clients
      security:
      - UserAuth: []
      responses:
        '200':
          description: refreshed access token
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/resp.auth.JWT'
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
        '500':
          description: Internal server error
  /auth/logout:
    delete:
      tags:
      - auth
      operationId: auth.logout.delete
      description: invalidate API token (i.e. logout)
      parameters:
      - name: jwt
        in: query
        required: false
        schema:
          type: string
      - name: gotoUrl
        in: query
        required: false
        schema:
          type: string
      responses:
        '200':
          description: successfully logged-out
        '302':
          description: redirection to the specified URL
        '400':
          description: invalid goto url
        '404':
          $ref: '#/components/responses/404NotFound'
        '500':
          description: Internal server error
  /isalive:
    get:
      tags:
      - isalive
      operationId: isalive.get
      description: see whether the Taranis instance is alive
      security: []
      responses:
        '200':
          description: server is alive
          content:
            application/json:
              schema:
                type: object
                properties:
                  isalive:
                    type: boolean
                    examples:
                    - true
  /health:
    get:
      tags:
      - health
      operationId: health.get
      description: see whether the Taranis instance dependencies are healthy
      security: []
      responses:
        '200':
          description: all required services are healthy
          content:
            application/json:
              schema:
                type: object
                properties:
                  healthy:
                    type: boolean
                    examples:
                    - true
                  services:
                    type: object
                    properties:
                      database:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      broker:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      workers:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
        '503':
          description: one or more required services are unhealthy
          content:
            application/json:
              schema:
                type: object
                properties:
                  healthy:
                    type: boolean
                    examples:
                    - false
                  services:
                    type: object
                    properties:
                      database:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      broker:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
                      workers:
                        type: string
                        enum:
                        - up
                        - down
                        - n/a
  /realtime/connect:
    post:
      tags:
      - realtime
      operationId: realtime.connect.post
      description: authenticate a Centrifugo connection using its dedicated proxy secret and the user's access cookie
      security:
      - RealtimeProxyKey: []
      responses:
        '200':
          description: connection credentials or a terminal disconnect
        '403':
          description: missing or invalid connect-proxy secret
  /realtime/broadcast:
    post:
      tags:
      - realtime
      operationId: realtime.broadcast_notification.post
      description: send a persistent notification to all connected users; requires ADMIN_OPERATIONS
      security:
      - UserAuth: []
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required:
              - message
              properties:
                message:
                  type: string
                  minLength: 1
                  maxLength: 500
      responses:
        '200':
          description: broadcast sent
        '400':
          description: invalid message
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '403':
          description: forbidden
        '503':
          description: realtime broadcast unavailable
  /realtime/clients:
    get:
      tags:
      - realtime
      operationId: realtime.connected_clients.get
      description: list connected realtime clients; requires ADMIN_OPERATIONS
      security:
      - UserAuth: []
      responses:
        '200':
          description: connected client and user information
          content:
            application/json:
              schema:
                type: object
                required:
                - num_clients
                - num_users
                - clients
                properties:
                  num_clients:
                    type: integer
                  num_users:
                    type: integer
                  clients:
                    type: array
                    items:
                      type: object
                      properties:
                        client_id:
                          type: string
                        user_id:
                          type: string
                        username:
                          type: string
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '403':
          description: forbidden
        '503':
          description: realtime presence unavailable
  /users:
    get:
      security:
      - UserAuth: []
      operationId: user.user_info.get
      tags:
      - users
      description: get the users details
      responses:
        '200':
          description: the user profile
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/user_response_detail'
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
        '500':
          description: Internal server error
  /users/profile:
    get:
      security:
      - UserAuth: []
      operationId: user.user_profile.get
      tags:
      - users
      description: get the user's profile
      responses:
        '200':
          description: the user profile
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/user_profile'
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
        '500':
          description: Internal server error
    put:
      security:
      - UserAuth: []
      operationId: user.user_profile.put
      tags:
      - users
      description: update the user's profile
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/user_profile'
      responses:
        '200':
          description: the updated user profile
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/user_profile'
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
        '500':
          description: Internal server error
    post:
      security:
      - UserAuth: []
      tags:
      - users
      description: handle profile
      operationId: user.user_profile.post
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
      responses:
        '200':
          description: success
          content:
            application/json:
              schema:
                type: object
        '201':
          description: created
          content:
            application/json:
              schema:
                type: object
        '400':
          description: invalid request
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '403':
          description: forbidden
        '404':
          $ref: '#/components/responses/404NotFound'
  /analyze/report-types:
    get:
      security:
      - UserAuth: []
      tags:
      - analyze
      description: get the types of report items
      operationId: analyze.report_types.get
      responses:
        '200':
          description: the types of report items
          content:
            application/json:
              schema:
                type: object
                properties:
                  total_count:
                    type: integer
                  items:
                    type: array
                    items:
                      $ref: '#/components/schemas/report_item_type'
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
  /analyze/report-items:
    get:
      security:
      - UserAuth: []
      tags:
      - analyze
      description: get the report items
      operationId: analyze.report_items.get
      parameters:
      - name: search
        in: query
        schema:
          type: string
      - name: completed
        in: query
        schema:
          type: string
      - name: range
        in: query
        schema:
          type: string
      - name: sort
        in: query
        schema:
          type: string
      - name: group
        in: query
        schema:
          type: string
      - name: offset
        in: query
        schema:
          type: integer
          minimum: 0
          format: int32
      - name: limit
        in: query
        schema:
          type: integer
          minimum: 1
          maximum: 200
      responses:
        '200':
          description: the report items
          content:
            application/json:
              schema:
                type: object
                properties:
                  total_count:
                    type: integer
                  items:
                    type: array
                    items:
                      $ref: '#/components/schemas/report_item'
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
    post:
      security:
      - UserAuth: []
      tags:
      - analyze
      description: add report item
      operationId: analyze.report_items.post
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/report_item'
      responses:
        '200':
          description: the ID of the newly created report item
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/report_item_response'
        '400':
          description: invalid input data
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
    put:
      security:
      - UserAuth: []
      tags:
      - analyze
      description: update report items
      operationId: analyze.report_items.put
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
      responses:
        '200':
          description: success
          content:
            application/json:
              schema:
                type: object
        '400':
          description: invalid request
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
    delete:
      security:
      - UserAuth: []
      tags:
      - analyze
      description: delete report items
      operationId: analyze.report_items.delete
      responses:
        '200':
          description: success
          content:
            application/json:
              schema:
                type: object
        '400':
          description: invalid request
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '404':
          $ref: '#/components/responses/404NotFound'
  /analyze/report-items/botactions:
    post:
      security:
      - UserAuth: []
      tags:
      - analyze
      description: queue a bot action for one or more report items
      operationId: analyze.report_bot_actions.post
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required:
              - bot_id
              properties:
                bot_id:
                  type: string
                report_id:
                  type: string
                report_ids:
                  type: array
                  items:
                    type: string
      responses:
        '200':
          description: success
          content:
            application/json:
              schema:
                type: object
        '400':
          description: invalid request
        '401':
          $ref: '#/components/responses/401Unauthorized'
        '403':
          description: forbidden
        '404':
          $ref: '#/components/responses/404NotFound'
  /analyze/report-items/publish-product:
    post:
      security:
      - UserAuth: []
      tags:
      - analyze
      operationId: analyze.report_items_publish_product.post
      description: 'Create a report and a product in a single request, then schedule
        an asynchronous render -> publish workflow for that product.


        Workflow behavior:

        - the report is created from the selected `report_item_type_id`

        - all report attributes are pre-populated from the report type''s attribute
        definitions and default values

        - `story_ids` are attached during report creation and must all resolve to
        existing stories

        - optional `attribute_overrides` are applied after default generation and
        must match exactly one generated report field by `group_title` and `title`

        - the product is always created with `auto_publish=true`

        - the product is always linked to the newly created report only

        - the selected product type must explicitly support the selected report type

        - the publish step is asynchronous; the endpoint only schedules render ->
        publish and does not wait for the worker result


        Permissions:

        - requires `ANALYZE_CREATE`

        - requires `PUBLISH_CREATE`

        - requires `PUBLISH_PRODUCT`


        Failure behavior:

        - validation failures reject the request before persistence

        - if queue scheduling fails after the report and product are committed, the
        endpoint returns `500` and includes the persisted resources in the response'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/report_publish_product_request'
            examples:
              minimal_success:
                summary: Create a report, create a product, and schedule publish
                value:
                  report:
                    title: CERT advisory for ACME VPN
                    report_item_type_id: '4'
                    story_ids:
                    - story-100
                    - story-101
                  product:
                    title: CERT Daily Report - ACME VPN
                    description: Daily delivery for the ACME VPN advisory
                    product_type_id: '7'
                    default_publisher: publisher-preset-42
              success_with_overrides:
                summary: Override generated report fields after default population
                value:
                  report:
                    title: ACME VPN incident brief
                    report_item_type_id: '4'
                    story_ids:
                    - story-100
                    attribute_overrides:
                    - group_title: Workflow Group
                      title: Executive Summary
                      value: Analyst supplied summary for the final report
                  product:
                    title: ACME VPN HTML briefing
                    description: HTML export for the ACME VPN incident brief
                    product_type_id: '7'
                    default_publisher: publisher-preset-42
      responses:
        '201':
          description: report and product were created and render -> publish was scheduled
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/report_publish_product_response'
              examples:
                success:
                  summary: Workflow scheduled successfully
                  value:
                    message: Report and product created; publish scheduled
                    report:
                      id: report-123
                      title: CERT advisory for ACME VPN
                      created: '2026-03-30T16:00:00+00:00'
                      last_updated: '2026-03-30T16:00:00+00:00'
                      completed: false
                      revision: 0
